sp_widget.client_script:
api.controller = function() {
    /* widget controller */
    var c = this;
    c.markComplete = function(sys_id) {
        var ga = new GlideAjax('TaskActionHandler');
        a.addParam('sysparm_name', 'completeTask');
        ga.addParam('sysparm_task_id', sys_id);
        ga.getXMLAnswer(function(response) {
            alert(response);
            location.reload();
        });
    };
    c.cancel = function(sys_id) {
        var ga = new GlideAjax('TaskActionHandler');
        ga.addParam('sysparm_name', 'cancelTask');
        ga.addParam('sysparm_task_id', sys_id);
        ga.getXMLAnswer(function(response) {
            alert(response);
            location.reload();
        });
    };


};

sp_widget.script:
(function() {
  var tasks = [];
  var gr = new GlideRecord('x_1790233_event_ma_event_task');
  gr.addQuery('status', '!=', 'Completed'); // Only show ongoing or pending tasks
  gr.addQuery('status', '!=', 'Cancelled');
  gr.orderBy('due_date');
  gr.query();

  while (gr.next()) {
    tasks.push({
      sys_id: gr.getUniqueValue(),
      name: gr.getValue('task_name'),
      event: gr.getDisplayValue('event_id'),
      due_date: gr.getDisplayValue('due_date'),
      assigned_to: gr.getDisplayValue('assigned_to'),
      status: gr.getValue('status')
    });
  }

  data.tasks = tasks;
})();
